// === Tab: mySketch ===
// Weekly Coding Challenge #WCCChallenge
// Theme: Continuous

// you should know that it looked like this for a year before I knew what was going on:
// https://editor.p5js.org/jordanne/sketches/ai2UV72MM
// atan2, people!

const amount = 10;
const esteemedWorms = [];
const palette =
  ["#55ff44", "#ff0088", "#ff7700", "#ffff22", "#11ccff", "#9911ff"];
let bg;

function setup() {
  createCanvas(500, 500);
  shuffle(palette, true);

  // make worms
  for (let i = 0; i < amount; i++) {
    let colour = palette[i % palette.length];
    let wormyFriend = new Wormoborous(50 + i * 20, colour);
    esteemedWorms.push(wormyFriend);
  }

  // make lissajous trail bg
  bg = createGraphics(500, 500);
  bg.stroke(120, 100);
  bg.translate(bg.width / 2, bg.height / 2);
  bg.noFill();
  for (let i = 0; i < amount; i++) {
    let radius = 50 + i * 20;
    let radiusY = radius;
    let factor = 3 / radius;
    let factor2 = 2 / radius;

    // make the setLineDash relative to the size
    bg.drawingContext.setLineDash([radius * 0.01, radius * 0.05]);

    let loopCount = TWO_PI * 6 / min(factor, factor2);
    let tStep = loopCount / 1000;  // Adjust this value for more or less detail
    bg.beginShape();
    for (let t = 0; t < loopCount; t += (Math.max(0.001, Math.abs(tStep)) || 1)) {
      let angle = t * factor;
      let x = cos(angle) * radius;
      let angle2 = t * factor2;
      let y = sin(angle2) * radiusY;
      bg.vertex(x, y);
    }
    bg.endShape();

  }
}

function draw() {
  noStroke();
  background(25, 25, 25, 60);
  image(bg, 0, 0);
  esteemedWorms.forEach(worm => {
    // worm.drawRing();
    noStroke();
    worm.draw();
  })
}
class Wormoborous {
  constructor(radius, colour) {
    this.radius = radius;
    this.radiusY = radius;
    this.colour = colour;
    this.length = 80;
    // 80+radius/2;
    this.circleSize;
    this.eyeAng;
    this.eyesY;
    this.eyesX;
    this.offset = 0;
    this.dir = 0; // Added direction variable
  }

  draw() {
    push();
    translate(width / 2, height / 2);

    for (let i = 0; i < this.length; i++) {
      //how spread apart each circle is
      this.factor = 3 / this.radius;
      //angle to pass into sin and cos
      this.factor2 = 2 / this.radius;
      this.angle = frameCount * this.factor - i * this.factor + this.offset;
      this.x = cos(this.angle) * this.radius;
      this.angle2 = frameCount * this.factor2 - i * this.factor2 + this.offset;
      this.y = sin(this.angle2) * this.radiusY;

      // Calculate direction of the worm
      if (i === 10) {
        let nextX = cos(frameCount * this.factor - (i+1) * this.factor + this.offset) * this.radius;
        let nextY = sin(frameCount * this.factor2 - (i+1) * this.factor2 + this.offset) * this.radiusY;
        this.dir = atan2(nextY - this.y, nextX - this.x);
      }

      if (i <= this.length / 20) {
        this.circleSize = 5;
      } else if (i <= this.length / 4) {
        this.circleSize += 0.5;
      } else if (i <= this.length / 5) {
        this.circleSize += 0.25;
      } else if (i <= this.length / 5.5) {
        this.circleSize -= 0.2;
      } else {
        this.circleSize -= 0.15;
      }

      fill(this.colour);
      circle(this.x, this.y, this.circleSize);

      // save the eye position at i = 10 to draw the eyes
      if (i === floor(this.length / 10)) {
        this.eyesX = this.x;
        this.eyesY = this.y;
        this.eyeAng = atan2(this.eyesY, this.eyesX);
      }
    }
    pop();

    // The eyes! draw them afterwards so they are on top
    push();
    translate(width / 2 + this.eyesX, height / 2 + this.eyesY);
    rotate(this.dir); // Rotate to the direction of the worm
    fill(255);
    circle(10, 4, 6);
    circle(10, -4, 6);
    fill(0);
    circle(10, 4, 4);
    circle(10, -4, 4);
    pop();
  }
}
